-- Permission vocabulary and system roles of the corpus module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the corpus permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('article:create'::text, 'article'::text, 'create'::text, 'Create article'::text),
            ('article:delete'::text, 'article'::text, 'delete'::text, 'Delete article'::text),
            ('article:purge'::text, 'article'::text, 'purge'::text, 'Purge article'::text),
            ('article:read'::text, 'article'::text, 'read'::text, 'Read article'::text),
            ('article:restore'::text, 'article'::text, 'restore'::text, 'Restore article'::text),
            ('article:update'::text, 'article'::text, 'update'::text, 'Update article'::text),
            ('article_category:create'::text, 'article_category'::text, 'create'::text, 'Create article category'::text),
            ('article_category:delete'::text, 'article_category'::text, 'delete'::text, 'Delete article category'::text),
            ('article_category:purge'::text, 'article_category'::text, 'purge'::text, 'Purge article category'::text),
            ('article_category:read'::text, 'article_category'::text, 'read'::text, 'Read article category'::text),
            ('article_category:restore'::text, 'article_category'::text, 'restore'::text, 'Restore article category'::text),
            ('article_category:update'::text, 'article_category'::text, 'update'::text, 'Update article category'::text),
            ('article_feedback:create'::text, 'article_feedback'::text, 'create'::text, 'Create article feedback'::text),
            ('article_feedback:delete'::text, 'article_feedback'::text, 'delete'::text, 'Delete article feedback'::text),
            ('article_feedback:purge'::text, 'article_feedback'::text, 'purge'::text, 'Purge article feedback'::text),
            ('article_feedback:read'::text, 'article_feedback'::text, 'read'::text, 'Read article feedback'::text),
            ('article_feedback:restore'::text, 'article_feedback'::text, 'restore'::text, 'Restore article feedback'::text),
            ('article_feedback:update'::text, 'article_feedback'::text, 'update'::text, 'Update article feedback'::text),
            ('article_link:create'::text, 'article_link'::text, 'create'::text, 'Create article link'::text),
            ('article_link:delete'::text, 'article_link'::text, 'delete'::text, 'Delete article link'::text),
            ('article_link:purge'::text, 'article_link'::text, 'purge'::text, 'Purge article link'::text),
            ('article_link:read'::text, 'article_link'::text, 'read'::text, 'Read article link'::text),
            ('article_link:restore'::text, 'article_link'::text, 'restore'::text, 'Restore article link'::text),
            ('article_link:update'::text, 'article_link'::text, 'update'::text, 'Update article link'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('article:create'::text, 'article'::text, 'create'::text, 'Create article'::text),
            ('article:delete'::text, 'article'::text, 'delete'::text, 'Delete article'::text),
            ('article:purge'::text, 'article'::text, 'purge'::text, 'Purge article'::text),
            ('article:read'::text, 'article'::text, 'read'::text, 'Read article'::text),
            ('article:restore'::text, 'article'::text, 'restore'::text, 'Restore article'::text),
            ('article:update'::text, 'article'::text, 'update'::text, 'Update article'::text),
            ('article_category:create'::text, 'article_category'::text, 'create'::text, 'Create article category'::text),
            ('article_category:delete'::text, 'article_category'::text, 'delete'::text, 'Delete article category'::text),
            ('article_category:purge'::text, 'article_category'::text, 'purge'::text, 'Purge article category'::text),
            ('article_category:read'::text, 'article_category'::text, 'read'::text, 'Read article category'::text),
            ('article_category:restore'::text, 'article_category'::text, 'restore'::text, 'Restore article category'::text),
            ('article_category:update'::text, 'article_category'::text, 'update'::text, 'Update article category'::text),
            ('article_feedback:create'::text, 'article_feedback'::text, 'create'::text, 'Create article feedback'::text),
            ('article_feedback:delete'::text, 'article_feedback'::text, 'delete'::text, 'Delete article feedback'::text),
            ('article_feedback:purge'::text, 'article_feedback'::text, 'purge'::text, 'Purge article feedback'::text),
            ('article_feedback:read'::text, 'article_feedback'::text, 'read'::text, 'Read article feedback'::text),
            ('article_feedback:restore'::text, 'article_feedback'::text, 'restore'::text, 'Restore article feedback'::text),
            ('article_feedback:update'::text, 'article_feedback'::text, 'update'::text, 'Update article feedback'::text),
            ('article_link:create'::text, 'article_link'::text, 'create'::text, 'Create article link'::text),
            ('article_link:delete'::text, 'article_link'::text, 'delete'::text, 'Delete article link'::text),
            ('article_link:purge'::text, 'article_link'::text, 'purge'::text, 'Purge article link'::text),
            ('article_link:read'::text, 'article_link'::text, 'read'::text, 'Read article link'::text),
            ('article_link:restore'::text, 'article_link'::text, 'restore'::text, 'Restore article link'::text),
            ('article_link:update'::text, 'article_link'::text, 'update'::text, 'Update article link'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
